import { renderToStaticMarkup } from "react-dom/server";
import Folder from "./Folder";

describe("Folder (trial T6, turn 1)", () => {
  it("wraps expanded children in a labelled group", () => {
    const html = renderToStaticMarkup(
      <Folder expanded label="Projects">
        <span>child</span>
      </Folder>
    );
    expect(html).toContain('role="group"');
    expect(html).toContain('aria-label="Projects"');
    expect(html).toContain("<span>child</span>");
  });

  it("renders nothing when collapsed", () => {
    const html = renderToStaticMarkup(
      <Folder expanded={false} label="Projects">
        <span>child</span>
      </Folder>
    );
    expect(html).toBe("");
  });
});

import { renderToStaticMarkup } from "react-dom/server";
import Folder from "./Folder";

describe("Folder without a label (trial T6, turn 2)", () => {
  it("renders children unwrapped", () => {
    const html = renderToStaticMarkup(
      <Folder expanded>
        <span>child</span>
      </Folder>
    );
    expect(html).toBe("<span>child</span>");
  });

  it("still groups with a label", () => {
    const html = renderToStaticMarkup(
      <Folder expanded label="Projects">
        <span>child</span>
      </Folder>
    );
    expect(html).toContain('role="group"');
  });
});
